def orientations(shape):
  variants=[]
  for refl in (False,True):
    for k in range(4):
      pts=set()
      for r,c in shape:
        if refl:c=-c
        for _ in range(k): r,c=c,-r
        pts.add((r,c))
      mr=min(r for r,c in pts); mc=min(c for r,c in pts)
      pts=frozenset((r-mr,c-mc) for r,c in pts)
      if pts not in variants:variants.append(pts)
  return variants

